//! Skills and commands: discovery, frontmatter, slash command registry.

pub mod registry;

pub mod learner;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub struct Skill {
    pub id: String,
    pub name: String,
    pub description: String,
    pub body: String,
    pub base_dir: PathBuf,
    /// File that defined the skill: `SKILL.md` for folder skills, the flat
    /// `*.md` file otherwise. `base_dir.join("SKILL.md")` is wrong for flat
    /// skills, so loaders must use this path.
    pub source: PathBuf,
    /// `metadata.freedas/autogenerated: true` written by the skill learner.
    pub autogenerated: bool,
    /// `metadata.freedas/autoinvoke: false` hides the skill from the model
    /// list while keeping it loadable via `@id` or the `skill` tool.
    pub autoinvoke: bool,
    /// A project-scoped skill replaced a global skill with the same id but
    /// different content. The project skill wins; callers/UI can warn on this.
    pub shadowed: bool,
}

impl Skill {
    /// Path of the file to read for the skill body.
    pub fn file_path(&self) -> &Path {
        &self.source
    }
    /// Whether the skill is advertised to the model.
    pub fn is_advertised(&self) -> bool {
        self.autoinvoke
    }
    /// Read the skill body from [`Self::source`], stripping frontmatter.
    /// Works for folder (`SKILL.md`) and flat (`*.md`) skills alike.
    pub fn load_body(&self) -> Option<String> {
        let text = std::fs::read_to_string(&self.source).ok()?;
        if let Some((_, body)) = freedas_agent::parse_frontmatter(&text) {
            Some(body)
        } else {
            Some(text)
        }
    }
}

/// Skills visible to the model (those without `autoinvoke: false`).
pub fn advertised(skills: &[Skill]) -> impl Iterator<Item = &Skill> {
    skills.iter().filter(|s| s.autoinvoke)
}

/// Collecting variant of [`advertised`] for callers that need a `Vec`.
pub fn advertised_skills(skills: &[Skill]) -> Vec<&Skill> {
    advertised(skills).collect()
}

fn parse_autoinvoke(front: &serde_json::Map<String, serde_json::Value>) -> bool {
    // Flat `freedas/autoinvoke` key (our frontmatter parser flattens the
    // `metadata:` block), plus a nested `metadata` object for forward
    // compatibility.
    if let Some(v) = front.get("freedas/autoinvoke") {
        return autoinvoke_value(v);
    }
    if let Some(meta) = front.get("metadata").and_then(|v| v.as_object())
        && let Some(v) = meta.get("freedas/autoinvoke")
    {
        return autoinvoke_value(v);
    }
    true
}

fn autoinvoke_value(v: &serde_json::Value) -> bool {
    match v {
        serde_json::Value::Bool(b) => *b,
        serde_json::Value::String(s) => {
            let s = s.trim().to_ascii_lowercase();
            !(s == "false" || s == "0" || s == "no" || s == "off" || s.is_empty())
        }
        serde_json::Value::Number(n) => n.as_i64().unwrap_or(1) != 0,
        serde_json::Value::Null => true,
        _ => true,
    }
}

fn parse_autogenerated(front: &serde_json::Map<String, serde_json::Value>) -> bool {
    if let Some(v) = front.get("freedas/autogenerated") {
        return v.as_bool().unwrap_or(v.as_str() == Some("true"));
    }
    if let Some(meta) = front.get("metadata").and_then(|v| v.as_object())
        && let Some(v) = meta.get("freedas/autogenerated")
    {
        return v.as_bool().unwrap_or(v.as_str() == Some("true"));
    }
    false
}

fn parse_skill_file(path: &Path, fallback_id: String) -> Option<Skill> {
    let text = std::fs::read_to_string(path).ok()?;
    let (front, body) = freedas_agent::parse_frontmatter(&text)
        .unwrap_or((serde_json::Value::Object(Default::default()), text.clone()));
    let front = front.as_object()?.clone();
    let raw_name = front
        .get("name")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let description = front
        .get("description")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let id = if raw_name.is_empty() {
        fallback_id.clone()
    } else {
        raw_name.clone()
    };
    let name = if raw_name.is_empty() {
        if fallback_id.is_empty() {
            "skill".to_string()
        } else {
            fallback_id
        }
    } else {
        raw_name
    };
    let base_dir = path.parent().unwrap_or(path).to_path_buf();
    let source = path.to_path_buf();
    // Only the marker written by the skill learner marks a skill as generated;
    // a user-chosen `auto-` prefix does not.
    let autogenerated = parse_autogenerated(&front);
    let autoinvoke = parse_autoinvoke(&front);
    Some(Skill {
        id,
        name,
        description,
        body,
        base_dir,
        source,
        autogenerated,
        autoinvoke,
        shadowed: false,
    })
}

/// Home base for `~/.claude`, `~/.agents`, and `~/.config` discovery.
/// `FREEDAS_HOME` relocates it (tests, containers); otherwise `$HOME`.
fn home_base() -> Option<PathBuf> {
    std::env::var_os("FREEDAS_HOME")
        .or_else(|| std::env::var_os("HOME"))
        .map(PathBuf::from)
}

pub fn discover(project_root: &Path) -> Vec<Skill> {
    discover_with(project_root, &[])
}

